-- CreateEnum
CREATE TYPE "SourceCategory" AS ENUM ('UNIVERSITY', 'GOVERNMENT', 'PROGRAM', 'PORTAL', 'NGO', 'OTHER');
CREATE TYPE "TrustLevel" AS ENUM ('UNVERIFIED', 'TRUSTED', 'OFFICIAL');
CREATE TYPE "CrawlStatus" AS ENUM ('QUEUED', 'ACTIVE', 'SUCCEEDED', 'FAILED', 'PAUSED', 'CANCELLED');
CREATE TYPE "FrontierStatus" AS ENUM ('PENDING', 'PROCESSING', 'VISITED', 'FAILED', 'SKIPPED');
CREATE TYPE "ScholarshipStatus" AS ENUM ('DISCOVERED', 'CRAWLING', 'EXTRACTED', 'NEEDS_REVIEW', 'VERIFIED', 'EXPIRED', 'REJECTED');
CREATE TYPE "VerificationStatus" AS ENUM ('EXTRACTED', 'CONFIRMED', 'CONFLICTING', 'REJECTED');
CREATE TYPE "FundingCategory" AS ENUM ('FULL', 'PARTIAL', 'UNKNOWN');
CREATE TYPE "AIStatus" AS ENUM ('SUCCEEDED', 'FAILED', 'REJECTED');

CREATE TABLE "Source" ("id" TEXT PRIMARY KEY, "providerName" TEXT NOT NULL, "homepage" TEXT NOT NULL, "scholarshipUrl" TEXT NOT NULL, "canonicalUrl" TEXT NOT NULL, "hostCountry" TEXT, "languages" TEXT[] DEFAULT ARRAY[]::TEXT[], "category" "SourceCategory" NOT NULL DEFAULT 'OTHER', "trustLevel" "TrustLevel" NOT NULL DEFAULT 'UNVERIFIED', "priority" INTEGER NOT NULL DEFAULT 50, "notes" TEXT, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Source_scholarshipUrl_key" ON "Source"("scholarshipUrl"); CREATE UNIQUE INDEX "Source_canonicalUrl_key" ON "Source"("canonicalUrl"); CREATE INDEX "Source_enabled_priority_idx" ON "Source"("enabled", "priority");
CREATE TABLE "SourcePage" ("id" TEXT PRIMARY KEY, "sourceId" TEXT NOT NULL REFERENCES "Source"("id") ON DELETE CASCADE, "url" TEXT NOT NULL, "canonicalUrl" TEXT NOT NULL, "title" TEXT, "language" TEXT, "content" TEXT NOT NULL, "contentHash" TEXT NOT NULL, "httpStatus" INTEGER NOT NULL, "fetchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "links" JSONB NOT NULL);
CREATE UNIQUE INDEX "SourcePage_canonicalUrl_key" ON "SourcePage"("canonicalUrl"); CREATE INDEX "SourcePage_sourceId_fetchedAt_idx" ON "SourcePage"("sourceId", "fetchedAt"); CREATE INDEX "SourcePage_contentHash_idx" ON "SourcePage"("contentHash");
CREATE TABLE "CrawlJob" ("id" TEXT PRIMARY KEY, "sourceId" TEXT REFERENCES "Source"("id") ON DELETE SET NULL, "rootUrl" TEXT NOT NULL, "status" "CrawlStatus" NOT NULL DEFAULT 'QUEUED', "maxDepth" INTEGER NOT NULL, "pageLimit" INTEGER NOT NULL, "visitedCount" INTEGER NOT NULL DEFAULT 0, "error" TEXT, "startedAt" TIMESTAMP(3), "finishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "CrawlJob_status_createdAt_idx" ON "CrawlJob"("status", "createdAt");
CREATE TABLE "CrawlFrontier" ("id" TEXT PRIMARY KEY, "crawlJobId" TEXT NOT NULL REFERENCES "CrawlJob"("id") ON DELETE CASCADE, "url" TEXT NOT NULL, "canonicalUrl" TEXT NOT NULL, "parentUrl" TEXT, "depth" INTEGER NOT NULL, "status" "FrontierStatus" NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "CrawlFrontier_crawlJobId_canonicalUrl_key" ON "CrawlFrontier"("crawlJobId", "canonicalUrl"); CREATE INDEX "CrawlFrontier_status_createdAt_idx" ON "CrawlFrontier"("status", "createdAt");
CREATE TABLE "SearchQuery" ("id" TEXT PRIMARY KEY, "query" TEXT NOT NULL, "language" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE UNIQUE INDEX "SearchQuery_query_language_key" ON "SearchQuery"("query", "language");
CREATE TABLE "SearchRun" ("id" TEXT PRIMARY KEY, "searchQueryId" TEXT NOT NULL REFERENCES "SearchQuery"("id") ON DELETE CASCADE, "account" TEXT NOT NULL, "resultCount" INTEGER NOT NULL DEFAULT 0, "newUrlCount" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL, "error" TEXT, "executedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SearchResult" ("id" TEXT PRIMARY KEY, "searchRunId" TEXT NOT NULL REFERENCES "SearchRun"("id") ON DELETE CASCADE, "url" TEXT NOT NULL, "canonicalUrl" TEXT NOT NULL, "title" TEXT, "snippet" TEXT, "position" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE UNIQUE INDEX "SearchResult_searchRunId_canonicalUrl_key" ON "SearchResult"("searchRunId", "canonicalUrl"); CREATE INDEX "SearchResult_canonicalUrl_idx" ON "SearchResult"("canonicalUrl");
CREATE TABLE "Scholarship" ("id" TEXT PRIMARY KEY, "sourceId" TEXT REFERENCES "Source"("id") ON DELETE SET NULL, "title" TEXT NOT NULL, "normalizedTitle" TEXT NOT NULL, "provider" TEXT, "institution" TEXT, "hostCountry" TEXT, "eligibleNationalities" TEXT[] DEFAULT ARRAY[]::TEXT[], "degreeLevels" TEXT[] DEFAULT ARRAY[]::TEXT[], "academicFields" TEXT[] DEFAULT ARRAY[]::TEXT[], "fundingCategory" "FundingCategory" NOT NULL DEFAULT 'UNKNOWN', "tuitionCoverage" TEXT, "monthlyStipend" TEXT, "accommodation" TEXT, "travelAllowance" TEXT, "healthInsurance" TEXT, "languageRequirements" TEXT, "academicRequirements" TEXT, "ageRestrictions" TEXT, "opensAt" TIMESTAMP(3), "deadline" TIMESTAMP(3), "academicYear" TEXT, "requiredDocuments" TEXT[] DEFAULT ARRAY[]::TEXT[], "applicationProcess" TEXT, "applicationUrl" TEXT, "sourceUrl" TEXT NOT NULL, "publicationDate" TIMESTAMP(3), "language" TEXT, "lastCheckedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "status" "ScholarshipStatus" NOT NULL DEFAULT 'DISCOVERED', "confidence" DOUBLE PRECISION, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Scholarship_status_deadline_idx" ON "Scholarship"("status", "deadline"); CREATE INDEX "Scholarship_normalizedTitle_provider_academicYear_idx" ON "Scholarship"("normalizedTitle", "provider", "academicYear");
CREATE TABLE "ScholarshipEvidence" ("id" TEXT PRIMARY KEY, "scholarshipId" TEXT NOT NULL REFERENCES "Scholarship"("id") ON DELETE CASCADE, "field" TEXT NOT NULL, "value" JSONB NOT NULL, "sourceUrl" TEXT NOT NULL, "evidenceText" TEXT NOT NULL, "verificationStatus" "VerificationStatus" NOT NULL DEFAULT 'EXTRACTED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "ScholarshipEvidence_scholarshipId_field_idx" ON "ScholarshipEvidence"("scholarshipId", "field");
CREATE TABLE "ScholarshipVersion" ("id" TEXT PRIMARY KEY, "scholarshipId" TEXT NOT NULL REFERENCES "Scholarship"("id") ON DELETE CASCADE, "snapshot" JSONB NOT NULL, "reason" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "ScholarshipVersion_scholarshipId_createdAt_idx" ON "ScholarshipVersion"("scholarshipId", "createdAt");
CREATE TABLE "AIInvocation" ("id" TEXT PRIMARY KEY, "task" TEXT NOT NULL, "model" TEXT NOT NULL, "inputHash" TEXT NOT NULL, "promptTokens" INTEGER, "completionTokens" INTEGER, "costUsd" DECIMAL(12,6), "status" "AIStatus" NOT NULL, "response" JSONB, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "AIInvocation_task_createdAt_idx" ON "AIInvocation"("task", "createdAt");
CREATE TABLE "APIUsage" ("id" TEXT PRIMARY KEY, "provider" TEXT NOT NULL, "account" TEXT, "operation" TEXT NOT NULL, "requests" INTEGER NOT NULL DEFAULT 1, "tokens" INTEGER, "costUsd" DECIMAL(12,6), "billingMonth" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX "APIUsage_provider_billingMonth_idx" ON "APIUsage"("provider", "billingMonth");
CREATE TABLE "DiscoveryMetric" ("id" TEXT PRIMARY KEY, "dimension" TEXT NOT NULL, "dimensionValue" TEXT NOT NULL, "searchesExecuted" INTEGER NOT NULL DEFAULT 0, "resultsReturned" INTEGER NOT NULL DEFAULT 0, "newRelevantUrls" INTEGER NOT NULL DEFAULT 0, "duplicateUrls" INTEGER NOT NULL DEFAULT 0, "uniqueScholarships" INTEGER NOT NULL DEFAULT 0, "verifiedScholarships" INTEGER NOT NULL DEFAULT 0, "costUsd" DECIMAL(12,6) NOT NULL DEFAULT 0, "periodStart" TIMESTAMP(3) NOT NULL, "periodEnd" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "DiscoveryMetric_dimension_dimensionValue_periodStart_periodEnd_key" ON "DiscoveryMetric"("dimension", "dimensionValue", "periodStart", "periodEnd");
CREATE TABLE "SystemSetting" ("key" TEXT PRIMARY KEY, "value" JSONB NOT NULL, "description" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL);
